
# Console scripts are now defined in terms of `hong2p.cli_entry_points` (see
# pyproject.toml), but those generated by older installs (which are not updated by
# changes to an editable install) import these from `hong2p`. Only importing
# `cli_entry_points` when one of these is requested, so that importing other hong2p
# modules doesn't also import everything it does (e.g. `hong2p.util` and matplotlib).
_cli_entry_points = (
    'thor2tiff_cli',
    'showsync_cli',
    'suite2p_params_cli',
    'print_data_root',
    'print_raw_data_root',
    'print_analysis_intermediates_root',
    'print_paired_thor_subdirs',
    'print_thorimage_subdir_notes',
    'save_requirements',
    'yaml2tex_cli',
    'cid2tex_cli',
    'build_docs_cli',
)

def __getattr__(name: str):
    if name in _cli_entry_points:
        from hong2p import cli_entry_points
        return getattr(cli_entry_points, name)

    raise AttributeError(f'module {__name__!r} has no attribute {name!r}')
